class Item:
    def __init__(self, name, quantity):
        self.name = name
        self.quantity = quantity

    def add_stock(self, amount):
        if amount < 0: raise ValueError("amount must be non-negative")
        self.quantity += amount

item = Item("notebook", 4)
item.add_stock(2)
print(item.quantity)
